use nu_engine::command_prelude::*;
use nu_engine::column::ColumnSeparator;
use nu_protocol::Signals;

use regex::Regex;

#[derive(Clone)]
pub struct SubCommand;

impl Command for SubCommand {
    fn name(&self) -> &str {
        "split column"
    }

    fn signature(&self) -> Signature {
        Signature::build("split column")
            .input_output_types(vec![
                (Type::String, Type::table()),
                (
                    // TODO: no test coverage (is this behavior a bug or a feature?)
                    Type::List(Box::new(Type::String)),
                    Type::table(),
                ),
            ])
            .required(
                "separator",
                SyntaxShape::String,
                "The character or string that denotes what separates columns.",
            )
            .switch("collapse-empty", "remove empty columns", Some('c'))
            .switch("regex", "separator is a regular expression", Some('r'))
            .rest(
                "rest",
                SyntaxShape::String,
                "Column names to give the new columns.",
            )
            .category(Category::Strings)
    }

    fn description(&self) -> &str {
        "Split a string into multiple columns using a separator."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["separate", "divide", "regex"]
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Split a string into columns by the specified separator",
                example: "'a--b--c' | split column '--'",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a string into columns of char and remove the empty columns",
                example: "'abc' | split column --collapse-empty ''",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a list of strings into a table",
                example: "['a-b' 'c-d'] | split column -",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
            Example {
                description: "Split a list of strings into a table, ignoring padding",
                example: r"['a -  b' 'c  -    d'] | split column --regex '\s*-\s*'",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
        ]
    }

    fn is_const(&self) -> bool {
        true
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req(engine_state, stack, 0)?;
        let rest: Vec<Spanned<String>> = call.rest(engine_state, stack, 1)?;
        let collapse_empty = call.has_flag(engine_state, stack, "collapse-empty")?;
        let has_regex = call.has_flag(engine_state, stack, "regex")?;

        let spec = ColumnSeparator::new(separator.item, separator.span, has_regex, call.head);
        let args = Arguments {
            rest,
            collapse_empty,
        };
        args.split_column(spec, input, engine_state.signals())
    }

    fn run_const(
        &self,
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req_const(working_set, 0)?;
        let rest: Vec<Spanned<String>> = call.rest_const(working_set, 1)?;
        let collapse_empty = call.has_flag_const(working_set, "collapse-empty")?;
        let has_regex = call.has_flag_const(working_set, "regex")?;

        let spec = ColumnSeparator::new(separator.item, separator.span, has_regex, call.head);
        let args = Arguments {
            rest,
            collapse_empty,
        };
        args.split_column(spec, input, working_set.permanent().signals())
    }
}

struct Arguments {
    rest: Vec<Spanned<String>>,
    collapse_empty: bool,
}

impl Arguments {
    fn split_column(
        self,
        spec: ColumnSeparator,
        input: PipelineData,
        signals: &Signals,
    ) -> Result<PipelineData, ShellError> {
        let separator_text = spec.text();
        let separator_span = spec.span();
        let is_regex = spec.is_regex();
        let command_span = spec.head();

        let regex = if is_regex {
            Regex::new(separator_text)
        } else {
            let escaped = regex::escape(separator_text);
            Regex::new(&escaped)
        }
        .map_err(|e| ShellError::GenericError {
            error: "Error with regular expression".into(),
            msg: e.to_string(),
            span: Some(separator_span),
            help: None,
            inner: vec![],
        })?;

        let rest = self.rest;
        let collapse_empty = self.collapse_empty;

        input.flat_map(
            move |v| {
                let s = match &v {
                    Value::String { val, .. } => Some(val.clone()),
                    _ => v.coerce_str().ok().map(|s| s.into_owned()),
                };
                if let Some(s) = s {
                    let split_result: Vec<_> = regex
                        .split(&s)
                        .filter(|x| !(collapse_empty && x.is_empty()))
                        .collect();
                    let positional: Vec<_> = rest.iter().map(|f| f.item.clone()).collect();

                    // If they didn't provide column names, make up our own
                    let mut record = Record::new();
                    if positional.is_empty() {
                        let mut gen_columns = vec![];
                        for i in 0..split_result.len() {
                            gen_columns.push(format!("column{}", i + 1));
                        }

                        for (&k, col) in split_result.iter().zip(&gen_columns) {
                            record.push(col, Value::string(k, command_span));
                        }
                    } else {
                        for (&k, col) in split_result.iter().zip(&positional) {
                            record.push(col, Value::string(k, command_span));
                        }
                    }
                    vec![Value::record(record, command_span)]
                } else {
                    match v {
                        Value::Error { error, .. } => {
                            vec![Value::error(*error.clone(), command_span)]
                        }
                        v => {
                            let span = v.span();
                            vec![Value::error(
                                ShellError::PipelineMismatch {
                                    exp_input_type: "string".into(),
                                    dst_span: command_span,
                                    src_span: span,
                                },
                                span,
                            )]
                        }
                    }
                }
            },
            signals,
        )
    }
}

#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn test_examples() {
        use crate::test_examples;

        test_examples(SubCommand {})
    }
}
